struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float hash(float n)
{
    return frac(sin(n) * 43758.5453f);
}

float hash2(float2 p)
{
    return frac(sin(dot(p, float2(127.1f, 311.7f))) * 43758.5453f);
}

float3 baseScene(float2 uv, float t)
{
    float3 col;
    col.r = 0.4f + 0.3f * sin(uv.x * 5.0f + t);
    col.g = 0.3f + 0.3f * sin(uv.y * 7.0f + t * 1.2f);
    col.b = 0.5f + 0.3f * cos((uv.x + uv.y) * 4.0f + t * 0.8f);
    float2 c = float2(0.5f + 0.2f * sin(t), 0.5f + 0.2f * cos(t * 0.7f));
    float d = length(uv - c);
    col += 0.3f * smoothstep(0.15f, 0.05f, d);
    return col;
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001f;
    float2 uv = i.uv;
    float timeBlock = floor(t * 4.0f);
    float glitchIntensity = step(0.7f, hash(timeBlock * 1.3f));
    float blockY = floor(uv.y * 20.0f);
    float blockRand = hash(blockY + timeBlock * 7.13f);
    float shift = 0.0f;
    if (glitchIntensity > 0.0f && blockRand > 0.6f)
    {
        shift = (blockRand - 0.6f) * 0.5f * sign(hash(blockY * 3.7f + timeBlock) - 0.5f);
    }
    float2 uvR = float2(uv.x + shift + 0.01f * glitchIntensity, uv.y);
    float2 uvG = float2(uv.x + shift, uv.y);
    float2 uvB = float2(uv.x + shift - 0.01f * glitchIntensity, uv.y);
    float3 col;
    col.r = baseScene(uvR, t).r;
    col.g = baseScene(uvG, t).g;
    col.b = baseScene(uvB, t).b;
    float flicker = 1.0f - 0.1f * glitchIntensity * hash(timeBlock * 5.0f);
    col *= flicker;
    float scanJitter = step(0.85f, hash(floor(uv.y * resolution_y) + timeBlock * 13.0f)) * glitchIntensity;
    col = lerp(col, float3(1.0f, 1.0f, 1.0f), scanJitter * 0.3f);
    return float4(col, 1.0f);
}
